#!/usr/bin/env node
/**
 * Copy our own emoji and icon sets into the app: `bun scripts/sync-openemoji.js`.
 *
 *   --openemoji <dir>   a checkout of github.com/profullstack/openemoji
 *   --openicon <dir>    a checkout of github.com/profullstack/openicon
 *
 * Both default to sibling checkouts (../openemoji, ../openicon next to this repo).
 *
 * Writes, and only writes, generated files:
 *   public/openemoji/64/<key>.webp       every base emoji (skin-tone variants stay
 *                                        native text: they would double the size)
 *   public/openemoji/index.json          the picker's search index, loaded on open
 *   public/openicon/sprite.svg           the OpenIcon symbols the chat UI uses
 *   src/lib/emoji/openemoji-keys.js      the keys we have artwork for, so a
 *                                        message renders without fetching the index
 *
 * Self-hosted on purpose: qrypt.chat also runs as an onion service, and an emoji
 * fetched from another origin would tell that origin who is chatting.
 */
import { readFileSync, writeFileSync, mkdirSync, copyFileSync, rmSync, existsSync } from 'node:fs';
import { resolve, join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 && process.argv[i + 1] ? resolve(process.argv[i + 1]) : fallback;
}

const emojiDir = arg('openemoji', resolve(root, '..', 'openemoji'));
const iconDir = arg('openicon', resolve(root, '..', 'openicon'));

/** OpenIcon keys used by the composer, the picker tabs and the file chips. */
export const ICONS = [
  'smile', 'paperclip', 'send', 'search', 'close', 'clock', 'users', 'leaf', 'coffee',
  'globe', 'trophy', 'lightbulb', 'hash', 'flag', 'reply', 'heart', 'plus-circle',
];

for (const [label, dir, file] of [
  ['openemoji', emojiDir, 'openemoji.json'],
  ['openicon', iconDir, 'openicon.json'],
]) {
  if (!existsSync(join(dir, file))) {
    console.error(`No ${file} in ${dir}. Pass --${label} <checkout of github.com/profullstack/${label}>.`);
    process.exit(1);
  }
}

const set = JSON.parse(readFileSync(join(emojiDir, 'openemoji.json'), 'utf8'));
const base = set.emoji.filter((e) => !e.base);
const groups = [...new Set(base.map((e) => e.group))];

const outEmoji = join(root, 'public', 'openemoji');
rmSync(outEmoji, { recursive: true, force: true });
mkdirSync(join(outEmoji, '64'), { recursive: true });
for (const e of base) {
  copyFileSync(join(emojiDir, e.webp.replace('{size}', '64')), join(outEmoji, '64', `${e.key}.webp`));
}

const index = {
  openemoji: set.openemoji,
  version: set.version,
  license: set.license,
  credit: 'OpenEmoji by Profullstack, Inc.',
  groups,
  // [char, name, group index, search words]: the key is derived from the char.
  emoji: base.map((e) => [e.char, e.name, groups.indexOf(e.group), (e.keywords || []).join(' ')]),
};
writeFileSync(join(outEmoji, 'index.json'), JSON.stringify(index));

const sprite = readFileSync(join(iconDir, 'sprite.svg'), 'utf8');
const symbols = ICONS.map((key) => {
  const match = sprite.match(new RegExp(`<symbol id="oi-${key}"[\\s\\S]*?</symbol>`));
  if (!match) throw new Error(`OpenIcon has no "${key}"`);
  return match[0];
});
mkdirSync(join(root, 'public', 'openicon'), { recursive: true });
writeFileSync(
  join(root, 'public', 'openicon', 'sprite.svg'),
  `<svg xmlns="http://www.w3.org/2000/svg">\n<!-- OpenIcon (MIT), github.com/profullstack/openicon -->\n${symbols.join('\n')}\n</svg>\n`
);

mkdirSync(join(root, 'src', 'lib', 'emoji'), { recursive: true });
writeFileSync(
  join(root, 'src', 'lib', 'emoji', 'openemoji-keys.js'),
  `// Generated by scripts/sync-openemoji.js from OpenEmoji ${set.version}. Do not edit.\n` +
    `export const OPENEMOJI_VERSION = ${JSON.stringify(set.version)};\n` +
    `export const OPENEMOJI_KEYS = new Set(${JSON.stringify(base.map((e) => e.key).join(' '))}.split(' '));\n`
);

console.log(`OpenEmoji ${set.version}: ${base.length} emoji in ${groups.length} groups; OpenIcon: ${symbols.length} symbols`);
